mapper.select:
select COMPANY_OR_DEPARTMENT as partnerName, count(1) as totalNum, SUM(IF(IS_FILING='是',1,0)) as filingNum, 0 as unFilingNum, 0 as filingRate from BIZ_CRM_HETONG where DELETE_FLAG = 'NOT_DELETE' and STATUS = '1'
and PARTNER_TYPE = #{partnerType}
and COMPANY_OR_DEPARTMENT is not null and COMPANY_OR_DEPARTMENT != '' and SEAL_DATE >= #{startDate} and SEAL_DATE <= #{endDate} group by COMPANY_OR_DEPARTMENT

select COMPANY_OR_DEPARTMENT as partnerName, count(1) as threeUnFilingNum from BIZ_CRM_HETONG where DELETE_FLAG = 'NOT_DELETE' and STATUS = '1'
and PARTNER_TYPE = #{partnerType}
and COMPANY_OR_DEPARTMENT is not null and COMPANY_OR_DEPARTMENT != '' and (IS_FILING is null or IS_FILING = '' or IS_FILING != '是' ) and SEAL_DATE >= #{startDate} and SEAL_DATE <= #{endDate} and DATE_ADD(SEAL_DATE,INTERVAL 3 MONTH) < now() group by COMPANY_OR_DEPARTMENT
